xpath_ast_node* parse_expression(int limit = 0)
{
	size_t old_depth = _depth;

	if (++_depth > xpath_ast_depth_limit)
		return error_rec();

	xpath_ast_node* n = parse_path_or_unary_expression();
	if (!n) return 0;

	n = parse_expression_rec(n, limit);

	_depth = old_depth;

	return n;
}

xpath_ast_node* error_rec()
{
